BEGIN
  IF (SELECT md5(string_agg(to_jsonb(t)::text, E'\n' ORDER BY t.id)) FROM public.techniques t WHERE t.test_type='sat') IS DISTINCT FROM 'ba881b7aa00e5032a7fe50a18783f5a2' THEN RAISE EXCEPTION 'Technique catalog changed'; END IF;
  IF (SELECT md5(string_agg(to_jsonb(ts)::text, E'\n' ORDER BY ts.technique_id, ts.skill_code)) FROM public.technique_skills ts JOIN public.techniques t ON t.id=ts.technique_id WHERE t.test_type='sat') IS DISTINCT FROM '6662c0eb93c8a378589ef58aec9a7dfc' THEN RAISE EXCEPTION 'Technique default mappings changed'; END IF;
  PERFORM q.id FROM public.questions_v2 q JOIN jsonb_array_elements(expected) e ON q.id=(e->>'question_id')::uuid ORDER BY q.id FOR UPDATE OF q;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(expected) e LEFT JOIN public.questions_v2 q ON q.id=(e->>'question_id')::uuid WHERE q.id IS NULL OR q.display_code IS DISTINCT FROM e->>'display_code' OR md5(to_jsonb(q)::text) IS DISTINCT FROM e->>'row_md5' OR NOT q.is_published OR q.is_broken OR q.deleted_at IS NOT NULL OR q.pool<>'standard') THEN RAISE EXCEPTION 'Question content, metadata, or eligibility changed'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(expected) e WHERE EXISTS (SELECT 1 FROM jsonb_array_elements_text(e->'add_ids') a WHERE NOT EXISTS (SELECT 1 FROM public.question_techniques qt WHERE qt.question_id=(e->>'question_id')::uuid AND qt.technique_id=a::uuid)) AND COALESCE((SELECT jsonb_agg(qt.technique_id ORDER BY qt.technique_id) FROM public.question_techniques qt WHERE qt.question_id=(e->>'question_id')::uuid),'[]'::jsonb) IS DISTINCT FROM e->'existing_ids') THEN RAISE EXCEPTION 'Question technique tags changed since review'; END IF;
  INSERT INTO public.question_techniques (question_id,technique_id,tagged_by)
  SELECT (e->>'question_id')::uuid,a::uuid,NULL FROM jsonb_array_elements(expected) e CROSS JOIN LATERAL jsonb_array_elements_text(e->'add_ids') a
  WHERE (SELECT count(*) FROM public.question_techniques qt WHERE qt.question_id=(e->>'question_id')::uuid)<2
  ON CONFLICT (question_id,technique_id) DO NOTHING;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(expected) e CROSS JOIN LATERAL jsonb_array_elements_text(e->'add_ids') a WHERE NOT EXISTS (SELECT 1 FROM public.question_techniques qt WHERE qt.question_id=(e->>'question_id')::uuid AND qt.technique_id=a::uuid)) THEN RAISE EXCEPTION 'Expected technique tag missing'; END IF;
END $guard$;
COMMIT;
SELECT count(*) AS total_tags FROM public.question_techniques;

